import numpy as np,json
m=json.load(open('/app/runs/init/meta.json'))
for n,pts in [('robot0_agentview_center',[(280,181),(281,183),(281,178),(272,178),(273,175),(268,183),(272,198)]),('robot0_agentview_right',[(223,181),(224,177),(219,180),(139,170)]),('robot0_eye_in_hand',[(280,150),(268,152)])]:
 d=np.load('/app/runs/init/depth_'+n+'.npy'); print(n,d.shape)
 print([(p,float(d[0,p[1],p[0]])) for p in pts]);print('percentiles',np.percentile(d[d>0],[5,25,50,75,95]))
 c=m['cameras'][n]; R=np.array(c['cam2world_gl'])[:3,:3]; t=np.array(c['cam2world_gl'])[:3,3]; K=np.array(c['intrinsic_cv']);
